import {test,expect,type Page} from '@playwright/test'
import {readFileSync,writeFileSync,existsSync,mkdirSync,chmodSync} from 'node:fs'
import {resolve} from 'node:path'
import {randomBytes} from 'node:crypto'
import {execFileSync} from 'node:child_process'

const origin='http://127.0.0.1:18080'
const enabled=process.env.NILART_RUN_DEMO_TESTS==='true'&&process.env.PLAYWRIGHT_BASE_URL===origin
test.skip(!enabled,'Writes only to the explicitly isolated integrated sandbox')
test.setTimeout(120000)
test.beforeEach(({page})=>{page.setDefaultTimeout(15000);mkdirSync(output,{recursive:true});chmodSync(output,0o700)})
const privateFile=process.env.NILART_BROWSER_AUDIT_ACCOUNTS||'/tmp/nilart-browser-audit-accounts.json'
const output=resolve(process.cwd(),'test-results/browser-audit')
const runFile='/tmp/nilart-browser-audit-results.json'
const tracing=new WeakSet<object>()
async function traceAfterLogin(page:Page){if(!test.info().title.startsWith('01 ')&&!test.info().title.startsWith('14 ')&&!tracing.has(page.context())){await page.context().tracing.start({screenshots:true,snapshots:true});tracing.add(page.context())}}
test.afterEach(async({context},info)=>{if(tracing.has(context)){const path=resolve(output,`trace-${info.title.slice(0,2)}-${Date.now()}.zip`);await context.tracing.stop({path});chmodSync(path,0o600)}record(info.title,{status:info.status==='passed'?'passed':info.status==='skipped'?'blocked':'failed',scope:'test execution',failure:info.status==='failed'?'See ignored Playwright screenshot/error context; no credentials recorded':undefined})})
function accounts(){return JSON.parse(readFileSync(privateFile,'utf8'))}
function record(name:string,data:Record<string,unknown>){const rows=existsSync(runFile)?JSON.parse(readFileSync(runFile,'utf8')):[];rows.push({name,at:new Date().toISOString(),...data});writeFileSync(runFile,JSON.stringify(rows,null,2),{mode:0o600})}
async function login(page:Page,phone:string,password:string){
 const state=`/tmp/nilart-browser-session-${phone.replace(/\D/g,'')}.json`;await page.context().clearCookies();
 if(existsSync(state)){await page.context().addCookies(JSON.parse(readFileSync(state,'utf8')).cookies);await page.goto('/en/account');await page.waitForLoadState('networkidle');if(!page.url().includes('/auth/')&&!await page.getByRole('heading',{name:'Access denied',exact:true}).count()){await traceAfterLogin(page);return}}
 await page.goto('/en/auth/login/password');await page.locator('#login-phone').fill(phone);await page.locator('#login-password').fill(password);await page.getByRole('button',{name:'Sign in',exact:true}).click();await expect(page.locator('#login-password')).toHaveCount(0,{timeout:20000});await page.context().storageState({path:state});chmodSync(state,0o600);await traceAfterLogin(page)
}
async function signUp(page:Page,phone:string,password:string){
 await page.goto('/en/auth/register');await page.locator('#otp-phone').fill(phone);await page.locator('.password-submit').click();await expect(page.locator('#verify-code').or(page.getByRole('alert').filter({hasText:'Too many requests'}))).toBeVisible();if(await page.locator('#verify-code').count()===0){await expect(page.locator('.password-submit')).toBeEnabled({timeout:65000});await page.locator('.password-submit').click()}await expect(page.locator('#verify-code')).toBeVisible();
 const shown=page.locator('.password-message strong');const code=await shown.count()?await shown.textContent():JSON.parse(execFileSync('docker',['exec','nilart-demo-api-1','python','-c','import sys,hashlib; from redis import Redis; from nilart.bootstrap.settings import settings; print(Redis.from_url(settings.redis_url).get("sandbox:sms:"+hashlib.sha256(sys.argv[1].encode()).hexdigest()).decode())',phone],{encoding:'utf8'})).code;expect(code).toMatch(/^\d{6}$/);await page.locator('#verify-code').fill(code!);await page.locator('.password-submit').click();await expect(page.locator('#registration-password')).toBeVisible();await page.locator('#registration-password').fill(password);await page.locator('#registration-confirm').fill(password);await page.locator('button[type="submit"]').click();await expect(page.locator('#registration-password')).toHaveCount(0,{timeout:20000});
}

test('01 create five dedicated accounts and grant roles through browser',async({browser,page})=>{
 mkdirSync(output,{recursive:true});
 if(!existsSync(privateFile)){const suffix=String(Date.now()).slice(-6);writeFileSync(privateFile,JSON.stringify({tag:`QA-${suffix}`,password:`QA-${randomBytes(20).toString('hex')}`,users:Object.fromEntries(['admin','customer','other','staff','artist'].map((role,i)=>[role,{phone:`+98913${suffix}${i}`}]))}),{mode:0o600})}
 chmodSync(privateFile,0o600);const a=accounts();
 for(const role of Object.keys(a.users)){
  if(a.users[role].registered)continue;
  const context=await browser.newContext({baseURL:origin});const p=await context.newPage();await signUp(p,a.users[role].phone,a.password);a.users[role].registered=true;writeFileSync(privateFile,JSON.stringify(a),{mode:0o600});await context.close();record(`account-${role}`,{status:'passed',method:'browser registration and password form; OTP read from isolated sandbox SMS inbox'})
 }
 const env=Object.fromEntries(readFileSync(resolve(process.cwd(),'../.env.demo'),'utf8').split('\n').map(l=>{const i=l.indexOf('=');return[l.slice(0,i),l.slice(i+1)]}));await login(page,'+989121110001',env.NILART_DEMO_ADMIN_PASSWORD);
 for(const [role,assigned] of [['admin','admin'],['staff','operations'],['artist','artist']]){
  await page.goto('/en/admin/users');await page.getByLabel('Search phone number',{exact:true}).fill(a.users[role].phone);await page.getByRole('button',{name:'Search',exact:true}).click();await expect(page.locator('tbody tr')).toHaveCount(1);await page.getByRole('button',{name:'Edit access',exact:true}).click();await page.getByRole('checkbox',{name:assigned,exact:true}).check();await page.getByLabel('Reason for change',{exact:true}).fill(`${a.tag} isolated browser acceptance role`);await page.getByRole('button',{name:'Confirm and save access',exact:true}).click();await expect(page.getByRole('status').filter({hasText:'Access saved and audited.'})).toBeVisible();record(`role-${role}`,{status:'passed',method:'browser account management'})
 }
 await login(page,a.users.admin.phone,a.password);await page.goto('/en/admin');await expect(page.locator('.ad-panel').first()).toBeVisible();record('dedicated-admin-login',{status:'passed'});
})

test('02 inspect all 56 required views in both languages and sizes',async({page})=>{
 test.setTimeout(900000);const a=accounts();await login(page,a.users.admin.phone,a.password);
 const manifest=JSON.parse(readFileSync(resolve(process.cwd(),'../docs/admin-integrated-acceptance.json'),'utf8'));
 const sources:Record<string,string>={products:'/api/v1/admin/catalog/entries/products',bundles:'/api/v1/admin/catalog/bundles',discounts:'/api/v1/admin/discounts/rules',materials:'/api/v1/admin/costing/resources?kind=material',recipes:'/api/v1/admin/costing/recipes',pricing:'/api/v1/admin/pricing/proposals',inventory:'/api/v1/admin/inventory',purchases:'/api/v1/admin/procurement/purchases',production:'/api/v1/admin/production',orders:'/api/v1/admin/orders',shipments:'/api/v1/admin/fulfillment/shipments',returns:'/api/v1/admin/order-requests?kind=return'};
 const ids:Record<string,string>={};for(const [key,url]of Object.entries(sources)){const r=await page.request.get(url);if(r.ok()){const body=await r.json();const rows=Array.isArray(body)?body:body.items??body.entries??[];if(rows.length)ids[key]=rows[0].id;if(key==='products'&&rows.length){const s=await page.request.get(`/api/v1/admin/catalog/entries/products/${rows[0].id}/skus`);if(s.ok()){const b=await s.json();const skus=Array.isArray(b)?b:b.items??[];if(skus.length)ids.sku=skus[0].id}}}}
 writeFileSync('/tmp/nilart-browser-audit-route-ids.json',JSON.stringify(ids),{mode:0o600});
 for(const view of manifest.views){
  if(process.env.NILART_BROWSER_AUDIT_VIEW_IDS&&!process.env.NILART_BROWSER_AUDIT_VIEW_IDS.split(',').includes(view.id))continue;
  let path=view.required_route as string;const key=path.includes('/products/')?'products':path.includes('/bundles/')?'bundles':path.includes('/discounts/')?'discounts':path.includes('/materials/')?'materials':path.includes('/boms/')?'recipes':path.includes('/pricing/reviews/')?'pricing':path.includes('/pricing/')?'sku':path.includes('/inventory/:')?'inventory':path.includes('/purchases/')?'purchases':path.includes('/production/')?'production':path.includes('/orders/')?'orders':path.includes('/shipments/')?'shipments':path.includes('/returns/')?'returns':'';
  if(path.includes(':')){if(!ids[key]){record(view.id,{status:'blocked',scope:'route inspection',reason:`No existing ${key} detail fixture`,required_route:path});continue}path=path.replace(/:(id|item|sku)/,ids[key])}
  console.log(`Inspecting ${view.id} ${path}`);
  for(const language of ['en','fa'])for(const width of [1440,390]){
   try{await page.setViewportSize({width,height:900});await page.goto(`/${language}${path}`);await expect(page.locator('main').first()).toBeVisible();await page.waitForLoadState('networkidle');
    const body=await page.locator('body').innerText();const missing=/This workflow is awaiting integration|This workflow is not connected yet|این بخش هنوز متصل نشده|این بخش هنوز به سرویس متصل نشده/.test(body);const denied=/Access denied|You do not have permission|دسترسی ندارید/.test(body);
    const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1);const alerts=await page.getByRole('alert').allTextContents();const buttons=await page.locator('.ad-panel button').evaluateAll(nodes=>nodes.filter(n=>!(n.getAttribute('aria-label')||n.getAttribute('title')||n.textContent?.trim())).length);
    const screenshot=`${view.id}-${language}-${width}.png`;await page.screenshot({path:resolve(output,screenshot),fullPage:true});
    record(view.id,{status:missing?'not implemented':denied||overflow||buttons?'failed':'passed',scope:'route/layout only; actions require separate evidence',path,language,width,overflow,unnamed_buttons:buttons,alerts,screenshot});
   }catch(error){record(view.id,{status:'failed',scope:'route inspection',path,language,width,error:String(error).slice(0,500)})}
  }
 }
})

async function choose(page:Page,label:string,option:string){await page.getByRole('combobox',{name:label,exact:true}).click();await page.getByRole('option',{name:option,exact:true}).click()}
async function fields(page:Page,values:Record<string,string>){for(const[label,value]of Object.entries(values))await page.getByLabel(label,{exact:true}).fill(value)}

