test('13 customer routes expose real recorded or empty states in both languages and sizes',async({page})=>{
 test.setTimeout(180000);const a=accounts();await login(page,a.users.customer.phone,a.password);
 for(const path of ['/account','/account/orders','/account/downloads','/account/favorites','/account/addresses','/account/profile','/account/security','/account/preferences','/account/support','/account/notifications','/account/requests','/account/commissions'])for(const lang of ['en','fa'])for(const width of [1440,390]){await page.setViewportSize({width,height:900});await page.goto(`/${lang}${path}`);await page.waitForLoadState('networkidle');await expect(page.locator('main')).toBeVisible();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);await page.keyboard.press('Tab');expect(await page.evaluate(()=>document.activeElement?.tagName)).not.toBe('BODY');await page.screenshot({path:resolve(output,`customer-${path.split('/').at(-1)}-${lang}-${width}.png`),fullPage:true});record(`customer-route-${path}`,{status:'passed',scope:'route/layout only',language:lang,width})}
})

test('14 browser password changes revoke old sessions and restore the test password',async({browser,page})=>{
 const a=accounts();await login(page,a.users.other.phone,a.password);const oldContext=await browser.newContext({baseURL:origin,storageState:await page.context().storageState()});const old=await oldContext.newPage();await old.goto('/en/account');
 const temporary=`QA-${randomBytes(24).toString('hex')}`;a.temporaryOtherPassword=temporary;writeFileSync(privateFile,JSON.stringify(a),{mode:0o600});
 async function change(current:string,next:string){await page.goto('/en/account/security');await page.locator('#security-current').fill(current);await page.locator('#security-next').fill(next);await page.locator('#security-confirm').fill(next);await page.getByRole('button',{name:'Change password',exact:true}).click();await expect(page.getByRole('heading',{name:'Your password has been changed',exact:true})).toBeVisible()}
 await change(a.password,temporary);await old.reload();await expect(old.getByRole('heading',{name:'Access denied',exact:true})).toBeVisible();await login(page,a.users.other.phone,temporary);await change(temporary,a.password);await login(page,a.users.other.phone,a.password);await page.goto('/en/account');await expect(page.locator('main')).toBeVisible();delete a.temporaryOtherPassword;writeFileSync(privateFile,JSON.stringify(a),{mode:0o600});record('security-password-session-revocation',{status:'passed',method:'browser password change → old context denied → fresh password login → password restored and fresh login'});await oldContext.close();
})

test('15 recorded list filters and reload controls are exercised through browser',async({page})=>{
 test.setTimeout(240000);const a=accounts();await login(page,a.users.admin.phone,a.password);page.on('dialog',d=>d.accept());const views=JSON.parse(readFileSync(resolve(process.cwd(),'../docs/admin-integrated-acceptance.json'),'utf8')).views;
 for(const view of views.filter((v:{required_route:string})=>!v.required_route.includes(':'))){
  await page.goto(`/en${view.required_route}`);await page.waitForLoadState('networkidle');const form=page.locator('.admin-filters').first();if(!await form.count())continue;
  const input=form.locator('input:not([type="hidden"]):not([type="date"])').first();if(!await input.count()||!await input.isEditable())continue;
  const apply=form.getByRole('button',{name:/^(Search|Load report|Load review queue|Find resources)$/}).first();if(!await apply.count()||!await apply.isEnabled())continue;
  const reads:string[]=[];const responses=(r:import('@playwright/test').Response)=>{if(r.url().includes('/api/')&&r.request().method()==='GET'&&r.status()===200)reads.push(new URL(r.url()).pathname+new URL(r.url()).search)};page.on('response',responses);
  await input.fill('QA-NO-MATCH-ACCEPTANCE');await apply.click();await page.waitForLoadState('networkidle');expect(await input.inputValue()).toBe('QA-NO-MATCH-ACCEPTANCE');const alerts=await page.locator('main [role="alert"]').allTextContents();expect(alerts.filter(s=>s.trim())).toEqual([]);expect(reads.some(url=>url.includes('QA-NO-MATCH-ACCEPTANCE'))).toBe(true);page.off('response',responses);record(`filters-${view.id}`,{status:'passed',method:'browser applies search and real backend acknowledges the filter',reads});
  const clear=page.getByRole('button',{name:/^Clear (search|filters)$/}).first();if(await clear.count()&&await clear.isEnabled()){await clear.click();await page.waitForLoadState('networkidle');await expect(input).toHaveValue('');record(`filter-clear-${view.id}`,{status:'passed',method:'browser clear restores unfiltered query'})}
 }
})

test('16 mixed checkout renews acceptance after an address change and freezes delivery types',async({page})=>{
 const a=accounts();await login(page,a.users.admin.phone,a.password);await page.goto(`/en/admin/artworks/${a.art}/edit`);const physical=await page.getByLabel('Slug',{exact:true}).inputValue();await page.goto(`/en/admin/artworks/${a.digital}/edit`);const digital=await page.getByLabel('Slug',{exact:true}).inputValue();await login(page,a.users.customer.phone,a.password);
 for(const slug of [physical,digital]){await page.goto(`/en/artworks/${slug}`);await page.getByRole('button',{name:'Add to basket',exact:true}).click();await expect(page.getByRole('status').filter({hasText:'Added to your basket.'})).toBeVisible()}
 await page.goto('/en/checkout/sandbox');const shipping=page.getByRole('combobox',{name:'Shipping method',exact:true});await shipping.click();await page.getByRole('option').filter({hasText:/QA-.*delivery/}).last().click();const confirmation=page.getByRole('checkbox',{name:'I confirm this is a sandbox test and accept the reviewed total, delivery and return terms.',exact:true});await confirmation.check();await expect(page.getByRole('button',{name:'Pay with Zarinpal sandbox',exact:true})).toBeEnabled();await page.getByRole('radio').nth(1).check();await expect(confirmation).not.toBeChecked();await expect(page.getByRole('button',{name:'Pay with Zarinpal sandbox',exact:true})).toBeDisabled();await expect(page.getByText('Calculating order terms…',{exact:true})).toHaveCount(0);await confirmation.check();await page.getByRole('button',{name:'Pay with Zarinpal sandbox',exact:true}).click();await expect(page).toHaveURL(/payment\/result\?id=/);await expect(page.getByRole('status').filter({hasText:'Order completed with no payment required'})).toBeVisible();const payment=await(await page.request.get(`/api/v1/payments/sandbox/${new URL(page.url()).searchParams.get('id')}`)).json();const order=await(await page.request.get(`/api/v1/account/orders/${payment.order_id}`)).json();expect(new Set(order.snapshot.items.map((i:{delivery:string})=>i.delivery))).toEqual(new Set(['physical','digital']));expect(order.snapshot.checkout_terms.weight_grams).toBe(100);expect(order.snapshot.items.find((i:{delivery:string})=>i.delivery==='digital').returnable).toBe(false);a.mixedOrder=payment.order_id;writeFileSync(privateFile,JSON.stringify(a),{mode:0o600});record('mixed-checkout-renewed-acceptance',{status:'passed',method:'browser physical + digital basket, address change clears acceptance, renewed acceptance and frozen mixed zero-charge order',order:payment.order_id})
})

test('17 concurrent browser checkouts cannot sell the last original twice',async({browser,page})=>{
 test.setTimeout(120000);const a=accounts(),tag=`${a.tag}-RACE-${randomBytes(2).toString('hex').toUpperCase()}`,title=`${tag} Original`,slug=tag.toLowerCase();await login(page,a.users.admin.phone,a.password);page.on('dialog',d=>d.accept());await page.goto(`/en/admin/media/${a.media}`);const imageTitle=await page.getByLabel('English title',{exact:true}).inputValue();await page.goto('/en/admin/artworks');await page.getByRole('button',{name:'New artwork',exact:true}).click();await fields(page,{'Persian title':`اثر ${tag}`,'English title':title,'Slug':slug,'Persian artist':'هنرمند آزمایش','English artist':'Sandbox artist','Image credit':'Synthetic browser race fixture','Price (toman)':'0','Shipping weight (grams)':'100'});await choose(page,'Return eligibility under policy','Eligible under policy');await page.getByLabel('Search images',{exact:true}).fill(imageTitle);await page.getByRole('button',{name:'Search',exact:true}).click();await page.getByRole('button',{name:`Add: ${imageTitle}`,exact:true}).click();await page.getByLabel('Reason',{exact:true}).fill(`${tag} explicit last-unit publication`);await page.getByRole('checkbox',{name:'I reviewed the definition and publication effect.',exact:true}).check();await page.getByRole('button',{name:'Confirm and publish artwork',exact:true}).click();await expect(page.getByText('Artwork definition saved.',{exact:true})).toBeVisible();const art=page.url().match(/[0-9a-f-]{36}/)![0];await page.goto('/en/admin/inventory/adjustments/new');await choose(page,'Opening item type','Unique original artwork');await page.getByLabel('Find item',{exact:true}).fill(slug);await page.getByRole('button',{name:'Find choices',exact:true}).click();await page.getByRole('button').filter({hasText:title}).click();await fields(page,{'Quantity in base units':'1','Total incoming value (toman)':'50','Reason and count reference':`${tag} counted single unit`});await page.getByRole('button',{name:'Confirm and record movement',exact:true}).click();await expect(page).toHaveURL(/\/inventory\/positions\/[0-9a-f-]{36}$/);const position=page.url().split('/').at(-1);
 const contexts=await Promise.all([browser.newContext({baseURL:origin}),browser.newContext({baseURL:origin})]);const pages=await Promise.all(contexts.map(c=>c.newPage()));
 for(let i=0;i<2;i++){const p=pages[i],user=i===0?a.users.customer:a.users.other;await login(p,user.phone,a.password);await p.goto('/en/account/addresses');await p.waitForLoadState('networkidle');{await p.getByRole('button',{name:'Add address',exact:true}).first().click();await p.getByLabel('Recipient full name',{exact:false}).fill(`${tag} recipient`);await p.getByLabel('Recipient phone',{exact:false}).fill(user.phone);await p.getByRole('combobox',{name:'Province',exact:true}).fill('Tehran');await p.getByRole('option',{name:'Tehran',exact:true}).click();await p.getByRole('combobox',{name:'City',exact:true}).fill('Tehran');await p.getByRole('option',{name:'Tehran',exact:true}).click();await p.getByLabel('Full address',{exact:false}).fill(`${tag} sandbox address`);await p.getByLabel('Postal code',{exact:false}).fill('1234567890');await p.getByRole('button',{name:'Save address',exact:true}).click();await expect(p.getByText('Address change saved.',{exact:true})).toBeVisible()};await p.goto('/en/cart');const remove=p.getByRole('button',{name:/^Remove from cart:/});await expect(remove.first().or(p.getByRole('heading',{name:'Your cart is empty.',exact:true}))).toBeVisible();while(await remove.count()){const count=await remove.count();await remove.first().click();await expect(remove).toHaveCount(count-1)};await p.goto(`/en/artworks/${slug}`);await p.getByRole('button',{name:'Add to basket',exact:true}).click();await expect(p.getByRole('status').filter({hasText:'Added to your basket.'})).toBeVisible();await p.goto('/en/checkout/sandbox');await p.getByRole('combobox',{name:'Shipping method',exact:true}).click();await p.getByRole('option').filter({hasText:/QA-.*delivery/}).last().click();await expect(p.getByText('Calculating order terms…',{exact:true})).toHaveCount(0);await p.getByRole('checkbox',{name:'I confirm this is a sandbox test and accept the reviewed total, delivery and return terms.',exact:true}).check();await expect(p.getByRole('button',{name:'Pay with Zarinpal sandbox',exact:true})).toBeEnabled()}
 const responses=pages.map(p=>p.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname==='/api/v1/payments/sandbox/checkout'));await Promise.all(pages.map(p=>p.getByRole('button',{name:'Pay with Zarinpal sandbox',exact:true}).click()));const outcomes=await Promise.all(responses);expect(outcomes.map(r=>r.status()).sort()).toEqual([200,409]);const winner=outcomes.findIndex(r=>r.status()===200),loser=1-winner;await expect(pages[winner].getByRole('status').filter({hasText:'Order completed with no payment required'})).toBeVisible();await expect(pages[loser].getByRole('alert').filter({hasText:'Payment initiation was not confirmed.'})).toBeVisible();const stock=await(await page.request.get(`/api/v1/admin/inventory/positions/${position}`)).json();expect(stock.quantity).toBe('1.000000');expect(stock.reserved).toBe('1.000000');record('last-unit-browser-concurrency',{status:'passed',method:'two independent customer browsers accept the same last-unit review and pay concurrently; one succeeds, one conflicts; exactly one reservation',art,position});await Promise.all(contexts.map(c=>c.close()));
})

test('18 SKU option combinations mapping and publication persist through browser',async({page})=>{
 const a=accounts();await login(page,a.users.admin.phone,a.password);page.on('dialog',d=>d.accept());await page.goto(`/en/admin/products/${a.catalogue.products}/variants`);await page.getByRole('button',{name:'Add option',exact:true}).click();await fields(page,{'Option Persian title':'اندازه آزمایش','Option English title':'QA Size','Value Persian title':'کوچک','Value English title':'Small'});await page.getByRole('button',{name:'Add combination',exact:true}).click();await page.getByLabel('Combination code (same as SKU code)',{exact:true}).fill(`${a.tag}-SKU`);const selection=page.getByRole('combobox',{name:'QA Size selected value',exact:true});await expect(selection).toHaveValue('');await selection.selectOption({label:'Small'});await page.getByRole('button',{name:'Save option draft',exact:true}).click();await expect(page.getByText('Option draft saved and audited.',{exact:true})).toBeVisible();await page.reload();await expect(page.getByLabel('Option English title',{exact:true})).toHaveValue('QA Size');await page.getByRole('button',{name:'Inspect mapping',exact:true}).click();await page.getByRole('button',{name:'Confirm mapping to current version',exact:true}).click();await expect(page.getByText('Mapping is current.',{exact:true})).toBeVisible();await page.getByRole('button',{name:'Publish SKU',exact:true}).click();await page.getByLabel('Publication reason',{exact:true}).fill(`${a.tag} approved mapped SKU visibility`);await page.getByRole('button',{name:'Confirm visibility change',exact:true}).click();await expect(page.getByRole('button',{name:'Unpublish SKU',exact:true})).toBeVisible();await page.reload();await page.getByRole('button',{name:'Inspect mapping',exact:true}).click();await expect(page.getByRole('button',{name:'Unpublish SKU',exact:true})).toBeVisible();record('sku-option-mapping-publication',{status:'passed',method:'browser bilingual option/value/combination draft, reload, version-pinned mapping, explicit SKU publication and reload',product:a.catalogue.products})
})
